#include "flight/structural_fracture.hpp"
#include "flight/structure_mesh.hpp"
#include "game.hpp"
#include "flight_scene.hpp"
#include "economy_storage.hpp"
#include <iostream>
using namespace hyperion;namespace hf=hyperion::flight;
namespace {
int checks=0;void check(bool b,const char* why){checks++;if(!b)throw std::runtime_error(why);}
std::vector<hf::FractureVertex> vertices(const hf::architecture::Builder& b){std::vector<hf::FractureVertex> v;for(size_t i=0;i<b.vertices.size()/3;i++)v.push_back({{b.vertices[i*3],b.vertices[i*3+1],b.vertices[i*3+2]},{b.normals[i*3],b.normals[i*3+1],b.normals[i*3+2]},{b.uv[i*2],b.uv[i*2+1]},{b.colours[i*4],b.colours[i*4+1],b.colours[i*4+2],b.colours[i*4+3]}});return v;}
void reject(const nlohmann::json& j,Game& g){bool threw=false;try{decodeEconomy(j,g.universe,g.s.hours);}catch(...){threw=true;}check(threw,"Corrupt structural snapshot accepted");}
}
int main(){try{
 for(int profile:std::array<int,8>{0,7,11,hf::StationCore,hf::StationWing,hf::LandingPad,hf::LoadingGantry,hf::FreightCrate})for(uint32_t seed:{0u,71u,0xffffffffu}){
  hf::architecture::Builder b;b.bevelBox({0,8,0},{16,16,14},Color{83,121,166,12},.3);b.ring({0,20,0},7,.35,Color{139,255,213,76},24);b.beam({-3,0,0},{4,32,0},.4,Color{121,93,164,3});auto source=vertices(b);auto result=hf::fractureStructure(source,profile,seed);check(result.parts.size()>=4&&result.parts.size()<=18,"Fragment budget exceeded");check(std::abs(result.sourceArea-result.fracturedArea)<.001,"Original architectural surface was lost");
  int caps=0;for(size_t part=0;part<result.parts.size();part++){auto& p=result.parts[part];if(p.vertices.empty())continue;caps+=p.capTriangles;hf::StructureRemains f;f.seed=seed;f.profile=profile;f.orbital=profile==hf::StationCore||profile==hf::StationWing;
   auto birth=hf::structurePose(f,p.bounds,int(part),0);check(hf::length(birth.centre-p.bounds.centre())<1e-8,"Release pose teleports architecture");
   for(const auto& v:p.vertices){check(hf::finite(v.position)&&hf::finite(v.normal)&&std::abs(hf::length(v.normal)-1)<1e-5,"Fractured normal is invalid");check(std::isfinite(v.uv[0])&&std::isfinite(v.uv[1]),"Fracture lost texture coordinates");auto initial=hf::fragmentPoint(birth,v.position-p.bounds.centre());check(hf::length(initial-v.position)<1e-8,"Fragments fail to reassemble source");check(v.colour[3]==12||v.colour[3]==76||v.colour[3]==3||v.colour[3]==16,"Fracture lost material identity");}
   auto previous=birth;for(int frame=1;frame<=1200;frame++){auto pose=hf::structurePose(f,p.bounds,int(part),frame/120.);check(hf::finite(pose.centre)&&hf::length(pose.centre-previous.centre)<1.8,"Fragment motion discontinuous");check(std::abs(hf::length(pose.right)-1)<1e-8&&hf::length(hf::cross(pose.right,pose.up)-pose.back)<1e-8,"Fragment frame lost rigidity");if(!f.orbital){auto half=p.bounds.half();double bottom=pose.centre.y-std::abs(pose.right.y)*half.x-std::abs(pose.up.y)*half.y-std::abs(pose.back.y)*half.z;check(bottom>=std::min(0.,p.bounds.low.y)-1e-6,"Fragment penetrates ground plane");}previous=pose;}
   if(!f.orbital){auto a=hf::structurePose(f,p.bounds,int(part),10),c=hf::structurePose(f,p.bounds,int(part),1000);check(hf::length(a.centre-c.centre)<1e-8&&hf::length(a.right-c.right)<1e-8,"Ground ruins keep moving after settling");}else check(hf::length(hf::structurePose(f,p.bounds,int(part),100000).centre-p.bounds.centre())<100,"Orbital debris escaped bounded persistent field");
  }check(caps>0,"Fractured solid lacks cut faces");
 }
 // Every cell of a closed box must have its own correctly wound end caps,
 // including where three cutting planes meet. Compare its signed volume with
 // its bounds, rather than merely counting cap triangles.
 for(uint32_t seed=0;seed<40;seed++){hf::architecture::Builder b;b.box({4,8,-3},{12,16,10},WHITE);auto f=hf::fractureStructure(vertices(b),hf::StationCore,seed);for(const auto& part:f.parts){if(part.vertices.empty())continue;double volume=0;for(size_t i=0;i<part.vertices.size();i+=3)volume+=hf::dot(part.vertices[i].position,hf::cross(part.vertices[i+1].position,part.vertices[i+2].position))/6.;auto size=part.bounds.high-part.bounds.low;check(std::abs(volume-size.x*size.y*size.z)<.0001,"Cut faces failed to seal a grid corner");}}
 // A whole source triangle lying on an internal cutting plane belongs to one
 // cell only. Exterior area conservation catches duplicate ownership.
 {hf::architecture::Builder b;b.box({0,1,0},{2,2,2},WHITE);auto v=vertices(b);double plane=-1+2*(.5+(hf::fractureNoise(4,1)-.5)*.12/2);hf::FractureVertex a{{plane,.2,-.3},{1,0,0},{},{1,2,3,4}},c=a,d=a;c.position.y=1.7;d.position.z=.7;v.insert(v.end(),{a,c,d});auto f=hf::fractureStructure(v,hf::FreightCrate,4);check(std::abs(f.sourceArea-f.fracturedArea)<1e-6,"Coplanar triangle counted twice");}
 Game g;g.enterFlight();auto& e=g.s.economy;auto& f=g.s.flight;auto& site=e.settlements.front();site.owner=0;auto siteId=site.id;int port=g.flightPort(siteId,false);f.ship.position=f.ports[port].position+f.ports[port].normal*60;f.docked=false;f.traffic.clear();g.prepareWorldObjects();auto id=facilityObjectId(siteId,Habitat,0);int index=-1;for(int i=0;i<int(f.worldObjects.size());i++)if(f.worldObjects[i].id==id)index=i;check(index>=0,"Missing generated building");auto before=f.worldObjects[index];f.damageWorld(index,1e8,-1,before.position,true);g.processFlightEvents();auto shape=e.worldDamage.at(id).structure;check(shape.valid&&shape.profile==hf::Habitat&&shape.variant==before.structureVariant&&shape.faction==before.structureFaction,"Collapse lost original occupancy or faction");check(hf::length(shape.origin-before.structureOrigin)<1e-8&&shape.born==g.s.hours,"Collapse lost placement or clock");check(f.worldDamage.at(id).structure.localBorn==f.time,"Birth did not bridge to flight time");double born=f.worldDamage.at(id).structure.localBorn;f.time+=1;e.damageRevision++;g.syncWorldDamage();check(f.worldDamage.at(id).structure.localBorn==born,"Damage sync restarted collapse");
 auto j=encodeEconomy(e);check(encodeEconomy(decodeEconomy(j,g.universe,g.s.hours))==j,"Structural ruins did not roundtrip exactly");check(!j["destruction"][id]["structure"].contains("localBorn"),"Transient flight clock leaked into save");
 for(const char* key:{"right","up","back"}){auto bad=j;bad["destruction"][id]["structure"][key]={0,0,0};reject(bad,g);}for(const char* key:{"profile","faction","variant","seed","ordinal","born"}){auto bad=j;bad["destruction"][id]["structure"][key]=-100;reject(bad,g);}auto bad=j;bad["destruction"][id]["structure"]["orbital"]=true;reject(bad,g);bad=j;bad["destruction"][id]["integrity"]=.5;reject(bad,g);
 // Rebuilding a habitat now waits for its actual evacuees to be delivered.
 g.openStrategy();auto kit=g.shipStock();kit[Components]+=3;kit[Crystal]+=1;g.storeShipStock(kit);f.cancelNavigation();f.ship.velocity={};f.ship.throttle=0;f.docked=false;f.dockedPort=-1;f.savedDock.clear();f.ship.position=e.worldDamage.at(id).position+e.worldDamage.at(id).normal*45;g.recoveryAction("recoveryRescue",id);check(e.worldDamage.at(id).recovery.aboard>0,"Habitat evacuees could not be rescued");f.dockAt(port);g.processFlightEvents();g.recoveryAction("recoveryDeliver",id);check(e.worldDamage.at(id).recovery.aboard==0,"Habitat evacuees could not be delivered");
 auto npc=e;auto* damaged=findSettlement(npc,siteId);damaged->owner=1;damaged->stock.fill(10000);damaged->treasury=100000;advanceEconomy(npc,g.universe,6);check(!npc.worldDamage.count(id)&&facilityIntegrity(*damaged,Habitat,0)==1,"NPC reconstruction left stale fragments");
 Stock stock{};stock.fill(1000);e.credits=100000;std::string message;check(construct(e,site,Habitat,stock,message)&&!e.worldDamage.count(id),"Reconstruction left stale structural ruins");g.syncWorldDamage();check(!f.worldDamage.count(id),"Reconstruction left active fragment draw record");
 std::cout<<"PASS: "<<checks<<" structural fracture checks / conserved textured geometry, cut faces, rigid continuous poses, gravity, orbit, saved identity and reconstruction\n";return 0;
}catch(const std::exception& e){std::cerr<<"FAIL: "<<e.what()<<'\n';return 1;}}
